from pathlib import Path
import base64

def dec(value: str) -> str:
    return base64.b64decode(value.encode('ascii')).decode('utf-8')

PAYLOADS = {
    'OLD_KSC': '',
    'NEW_KSC': '',
    'OLD_FRAME': 'ZnVuY3Rpb24gZnJhbWUobm93KXsKICBsZXQgZHQgPSAobm93IC0gbGFzdFQpIC8gMTAwMDsKICBpZiAoZHQgPiAwLjA1KSBkdCA9IDAuMDU7IC8vIGNsYW1wCiAgbGFzdFQgPSBub3c7',
    'NEW_FRAME': '',
    'OLD_HEX': 'ZnVuY3Rpb24gYmxlbmQoYzEsIGMyLCBmKXsKICBmdW5jdGlvbiBoZXgoYyl7IHJldHVybiBjLnN0YXJ0c1dpdGgoJyMnKSA/IFtwYXJzZUludChjLnNsaWNlKDEsMyksMTYpLCBwYXJzZUludChjLnNsaWNlKDMsNSksMTYpLCBwYXJzZUludChjLnNsaWNlKDUsNyksMTYpXSA6IFsxMjAsMTYwLDIwMF07IH0=',
    'NEW_HEX': '',
}

ROOT = Path('.')

def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected 1 match, found {count}')
    return text.replace(old, new, 1)

index_path = ROOT / 'index.html'
index = index_path.read_text(encoding='utf-8')
index = replace_once(index, dec(PAYLOADS['OLD_KSC']), dec(PAYLOADS['NEW_KSC']), 'KSC cache repair')
index = replace_once(index, dec(PAYLOADS['OLD_FRAME']), dec(PAYLOADS['NEW_FRAME']), 'frame timing repair')
index = replace_once(index, dec(PAYLOADS['OLD_HEX']), dec(PAYLOADS['NEW_HEX']), 'colour fallback repair')
index_path.write_text(index, encoding='utf-8')
print('SHVAPE code repair applied')
